-- Target schema for the new deployment, generated by gen_target_schema.py.
-- 54 tables: 23 that carry rows, 31 that start empty and are filled by
-- the game itself. A table missing here is a subsystem that dies on contact.

-- pgmigrate ddl.py — generated PostgreSQL schema (pre-load).
-- Unvalidated against a real dump. Read the report before running this.

CREATE TABLE maxsec_applications (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  discord_id bigint NOT NULL,
  discord_name varchar(128) DEFAULT NULL,
  ig_name varchar(128) DEFAULT NULL,
  pid varchar(20) DEFAULT NULL,
  dob varchar(64) DEFAULT NULL,
  time_on_server varchar(255) DEFAULT NULL,
  cop_experience text DEFAULT NULL,
  why text DEFAULT NULL,
  disciplinary text DEFAULT NULL,
  status text NOT NULL DEFAULT 'pending',
  reviewer_id bigint DEFAULT NULL,
  reviewer_name varchar(128) DEFAULT NULL,
  decision_note varchar(512) DEFAULT NULL,
  review_msg_id bigint DEFAULT NULL,
  created_at timestamptz DEFAULT now(),
  decided_at timestamptz DEFAULT NULL,
  thread_id bigint DEFAULT NULL,
  faction varchar(8) NOT NULL DEFAULT 'apd',
  CONSTRAINT apd_applications_status_chk CHECK (status IN ('pending', 'accepted', 'denied')),
  CONSTRAINT maxsec_applications_pkey PRIMARY KEY (id)
);
CREATE TABLE atm_skimmers (
  atm_key varchar(32) NOT NULL,
  owner_uid varchar(32) NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT atm_skimmers_pkey PRIMARY KEY (atm_key)
);
CREATE TABLE bans (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  playerid varchar(17) NOT NULL,
  reason text DEFAULT NULL,
  banned_by varchar(40) DEFAULT NULL,
  until timestamptz DEFAULT NULL,
  created timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT bans_pkey PRIMARY KEY (id)
);
CREATE TABLE bones_dm (
  id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  uid varchar(32) NOT NULL,
  name varchar(32) NOT NULL,
