COMMENT ON TABLE opfor_whitelist IS '4th faction (OPFOR) whitelist - mirrors cop coplevel/copretired; no ranks set yet (teaser)';

-- Indexes. Names are table-qualified: MySQL index names are unique
-- per table, PostgreSQL's are unique per schema.
CREATE INDEX apd_applications_k_discord ON maxsec_applications (discord_id);
CREATE INDEX apd_applications_k_status ON maxsec_applications (status);
CREATE INDEX apd_applications_k_pid ON maxsec_applications (pid);
CREATE INDEX bans_ix_pid ON bans (playerid);
CREATE INDEX bones_dm_idx_reply ON bones_dm (left(reply, 1), delivered);
CREATE INDEX bones_dm_idx_uid ON bones_dm (uid, id);
CREATE INDEX bot_commands_ix_status ON bot_commands (status);
CREATE INDEX bounties_target_uid ON bounties (target_uid);
CREATE INDEX casino_chips_idx_pid ON casino_chips (pid);
CREATE INDEX clankr_alerts_ts ON clankr_alerts (ts);
CREATE INDEX clankr_alerts_playerid ON clankr_alerts (playerid);
CREATE INDEX clankr_alerts_severity ON clankr_alerts (severity);
CREATE UNIQUE INDEX discord_links_uniq_pid ON discord_links (playerid);
CREATE INDEX enrique_log_k_pid_used ON enrique_log (playerid, used_at);
CREATE INDEX enrique_log_k_ready ON enrique_log (pinged, ready_at);
CREATE INDEX exchange_idx_lookup ON exchange (active, buyorsell, left(classname, 64));
CREATE INDEX gang_bank_log_idx_gang ON gang_bank_log (gangid, id);
CREATE UNIQUE INDEX gang_vehicles_uq_gang_plate ON gang_vehicles (gang_id, plate);
CREATE INDEX gang_vehicles_gang_id ON gang_vehicles (gang_id, active, type);
CREATE UNIQUE INDEX gangs_name ON gangs (name);
CREATE INDEX house_rigs_idx_oid ON house_rigs (oid);
CREATE INDEX house_rigs_idx_owner ON house_rigs (owner);
CREATE UNIQUE INDEX houses_oid_unique ON houses (oid);
CREATE INDEX houses_owners ON houses (owners);
CREATE INDEX houses_worldspace ON houses (left(worldspace, 64));
CREATE UNIQUE INDEX houses_malden_oid_unique ON houses_malden (oid);
CREATE INDEX houses_malden_owners ON houses_malden (owners);
CREATE INDEX houses_malden_worldspace ON houses_malden (left(worldspace, 64));
CREATE INDEX loadouts_pid_side ON loadouts (pid, side);
