-- ON UPDATE CURRENT_TIMESTAMP replacements. Dropping these freezes
-- the column forever, and one of them drives an activity filter.
CREATE OR REPLACE FUNCTION set_casino_chip_pity_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS casino_chip_pity_updated_at_on_update ON casino_chip_pity;
CREATE TRIGGER casino_chip_pity_updated_at_on_update
    BEFORE UPDATE ON casino_chip_pity
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION set_casino_chip_pity_updated_at();
